var sb = new System.Text.StringBuilder();
string[] roots = { "Wide Stair for wallMerge", "Wide Stair for wallMerge (1)" };
foreach (var rootName in roots)
{
    var go = GameObject.Find(rootName);
    if (go == null) { sb.AppendLine($"NOT FOUND: {rootName}"); continue; }
    sb.AppendLine($"=== {rootName} (id={go.GetInstanceID()}) ===");
    var mrs = go.GetComponentsInChildren<MeshRenderer>(true);
    sb.AppendLine($"  MeshRenderers: {mrs.Length}");
    int idx = 0;
    foreach (var mr in mrs)
    {
        idx++;
        var t = mr.transform;
        var path = new System.Text.StringBuilder(t.name);
        while (t.parent != go.transform && t.parent != null) { t = t.parent; path.Insert(0, t.name + "/"); }
        sb.AppendLine($"  [{idx}] {path}  (id={mr.gameObject.GetInstanceID()})");
        var mats = mr.sharedMaterials;
        for (int i = 0; i < mats.Length; i++)
        {
            var m = mats[i];
            if (m == null) { sb.AppendLine($"      slot {i}: <MISSING MATERIAL>"); continue; }
            string sname = m.shader != null ? m.shader.name : "<null shader>";
            string mname = m.name ?? "<null>";
            string mpath = UnityEditor.AssetDatabase.GetAssetPath(m);
            sb.AppendLine($"      slot {i}: '{mname}'  shader='{sname}'  path='{mpath}'");
            // Check key textures
            string[] tprops = { "_BaseColorMap", "_MainTex", "_BaseMap", "_NormalMap", "_MaskMap" };
            foreach (var tp in tprops)
            {
                if (!m.HasProperty(tp)) continue;
                var tex = m.GetTexture(tp);
                string ts = tex == null ? "<null>" : tex.name;
                string tpath = tex == null ? "" : UnityEditor.AssetDatabase.GetAssetPath(tex);
                sb.AppendLine($"        {tp}: {ts} ({tpath})");
            }
        }
        var mf = mr.GetComponent<MeshFilter>();
        if (mf != null && mf.sharedMesh != null)
            sb.AppendLine($"      mesh: '{mf.sharedMesh.name}' verts={mf.sharedMesh.vertexCount}");
    }
}
return sb.ToString();
